import{newStory,setupDecision,currentPlot,currentNode,locks,storyAction,restoreStory,companionId,trustValue}from'./story-manager.js';
const [world,plots]=await Promise.all([fetch('data/world.json').then(r=>r.json()),fetch('data/plots.json').then(r=>r.json())]);
const $=id=>document.getElementById(id),escapeHtml=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),AUTO='meteor-v03-auto',MANUAL='meteor-v03-manual';let state=newStory(world),view='story',acting=false,first=true,restoreError='';
try{const raw=localStorage.getItem(AUTO);if(raw){state=restoreStory(JSON.parse(raw),world,plots);first=false}}catch(e){restoreError=e.message;first=false}
const knownFlags={concealed:'숨긴 유성의 흔적',meteor_read:'신력의 결',beacon:'남겨 둔 빛',bandaged:'상처를 묶은 기억',care:'치료의 기억',self_reliant:'홀로 서려는 마음',herbalist:'약초 지식',shared_knowledge:'함께 나눈 지식',stream_path:'계곡의 퇴로',shelter:'안쪽 은신처',warned:'비상시의 신호',unwarned:'잠깐의 평온',trap:'수리한 덫',trap_lore:'덫의 구조',safe_path:'안전한 길',orders:'복원한 명령',marks:'남은 표식',letter:'보관한 전갈',burned_letter:'태워 버린 전갈',breathing:'맞춘 호흡',trained:'시험한 힘',focused:'정리된 감각',ward:'보호 경계',alarm:'경보 장치',weak_point:'기운이 빠지는 틈',signal:'익힌 신호',scout_path:'예상한 추적 경로',challenge:'위치를 드러낸 외침',promise:'서로 지킬 약속',retreat_plan:'함께 정한 퇴로',duty:'각자의 의무',false_report:'거짓 보고',parley:'협상의 여지',scout_caught:'붙잡은 정찰자',scout_talk:'정찰자와 대화',scout_seen:'목격한 정찰자',scout_wounded:'정찰자와 충돌',scout_detained:'정찰자 억류',uncertain_report:'흐려진 위치 정보',defiance:'남긴 경고',truce:'잠정 휴전',peace_kept:'싸움 없이 지킨 평온',repelled:'막아 낸 급습',deceived:'속인 추적자',sheltered:'숨긴 사람들',evacuated:'지켜 낸 거처',battle_victory:'전투에서 버틴 기억',battle_defeat:'후퇴의 기억',battle_fled:'확보한 퇴로',battle_truce:'전투 중 휴전'};
function message(t){$('toast').textContent=t;$('toast').classList.add('visible');setTimeout(()=>$('toast').classList.remove('visible'),3500)}function saveAuto(){try{localStorage.setItem(AUTO,JSON.stringify(state))}catch{message('브라우저에 저장할 수 없습니다. 기록 파일로 내보내 주세요.')}}function openModal(html){$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal()}$('close').onclick=()=>$('modal').close();function meter(label,v,max=100,cls=''){return`<div class="statline"><span>${label}</span><strong>${v} / ${max}</strong></div><div class="bar ${cls}"><i style="width:${Math.min(100,Math.max(0,v/max*100))}%"></i></div>`}
function draw(){const p=state.characters[state.player],c=state.characters[companionId(state)];$('clock').textContent=`${state.day}일차 · 완료 ${state.tick}턴 / 유성이 내린 산속`;$('scene-state').textContent=state.combat?'전투 진행 중':state.story.ending?'첫 장 완료':'한 지역 · 분기형 스토리';$('player').innerHTML=`<div class="portrait"><span class="glyph">${state.player==='jihyo'?'陰':'白'}</span><small>${state.player==='jihyo'?'THE VESSEL':'THE GUARDIAN'}</small></div><div class="player-name">${escapeHtml(p.name)}</div><div class="subtitle">${escapeHtml(p.title)}</div>${meter('체력',p.hp,p.maxHp,'hp')}${meter('기력',p.energy,p.maxEnergy)}${meter('정신 안정',p.stability)}<div class="stats">${[['힘',p.power],['민첩',p.agility],['통찰',p.insight],['의지',p.will]].map(([a,b])=>`<span>${a}<b>${b}</b></span>`).join('')}</div>`;$('companion').innerHTML=`<div class="npc-row"><span class="npc-icon">${c.name[0]}</span><span>${c.name}<small>같은 산속에 머무는 인물</small></span></div>${meter('당신을 향한 신뢰',trustValue(state),100,'gold')}`;$('inventory').innerHTML=`<div class="inventory"><span>약초</span><b>${state.inventory.herb}개</b></div>`;$('progress').textContent=`서브 ${state.story.completed.length}/10 · 메인 ${state.story.mainDone.length}/3`;$('plot-progress').innerHTML=plots.mains.map((p,i)=>`<div class="clue">${i+1}. ${p.title}<small>${state.story.mainDone.includes(p.id)?'완료':state.story.active?.plot===p.id?'진행 중':`서브 플롯 ${p.threshold}개 완료 후 진행`}</small></div>`).join('');$('clues').innerHTML=state.story.flags.filter(f=>knownFlags[f]).map(f=>`<div class="clue">${knownFlags[f]}</div>`).join('')||'<p class="empty">작은 선택이 남긴 준비가 여기에 쌓입니다.</p>';
$('next-turn').disabled=acting||!!state.story.ending;$('next-turn').textContent=acting?'처리 중…':state.story.ending?'이 장의 이야기 완료':state.pending?'선택 이어하기 →':'다음 턴 →';$('turn-help').textContent=state.combat?`${state.day}일차 · 제${state.tick+1}턴 사건 / 전투 라운드 ${state.combat.round}`:state.pending?`${state.day}일차 · 제${state.tick+1}턴 선택 대기`:`오늘의 행동 ${state.todayActions}회 · 밤을 보내야 날짜가 바뀝니다.`;
$('story').hidden=view!=='story';$('page').hidden=view==='story';document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===view));if(view==='story')drawStory();else drawPage();}
function drawStory(){const html=state.story.records.slice(-30).map(r=>`<article class="turn-card"><div class="eyebrow">${r.day}일차 · 제${r.turn}턴</div><h3>${escapeHtml(r.title)}</h3><div class="selection">선택: ${escapeHtml(r.label)}</div><div class="entry">${escapeHtml(r.text)}</div>${r.check?`<div class="entry check">${r.check.result} · ${r.check.roll} / ${r.check.chance}</div>`:''}<div class="change-list">${r.changes.map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div></article>${r.endDay>r.day?`<div class="day-divider">밤을 보냈습니다 — ${r.endDay}일차 시작</div>`:''}`).join('');$('log').innerHTML=html||'<div class="entry"><span class="stamp">서막</span>하얀 유성이 숲에 떨어졌다. 연기가 걷히고, 백호와 지효가 처음 마주친다.<br>작은 사건을 선택하고, 그 선택이 큰 사건으로 이어지는 모습을 확인하세요.</div>';$('log').scrollTop=$('log').scrollHeight;$('battle').innerHTML=state.combat?`<div class="battle"><h3>${escapeHtml(state.combat.name)}</h3>${meter('상대 체력',state.combat.hp,state.combat.maxHp,'hp')}<p>라운드 ${state.combat.round} · ${['근거리','중거리','원거리'][state.combat.distance]}</p>${state.log.filter(e=>e.type==='combat'||e.type==='check').slice(-4).map(e=>`<small>${escapeHtml(e.text)}</small><br>`).join('')}</div>`:'';const e=plots.endings[state.story.ending];$('ending').innerHTML=e?`<article class="ending-card"><div class="eyebrow">CHAPTER COMPLETE</div><h2>${e.title}</h2><p>${e.text}</p><p>이번 큰 사건: ${{quiet:'아무도 오지 않은 길',snake:'뱀의 직접 개입',minions:'부하들의 급습'}[state.story.route]}</p><p>${state.story.routeReasons.map(escapeHtml).join('<br>')}</p><small>서브 플롯 10개 · 메인 플롯 3개를 마쳤습니다.<br>다시 시작하면 다른 준비와 다른 결말을 선택할 수 있습니다.</small></article>`:'';}
function drawPage(){if(view==='map')$('page').innerHTML='<h2 class="page-title">유성이 내린 산속</h2><p class="empty">이번 장은 이 산 한 지역에서만 진행됩니다.<br>거처 · 계곡 · 산길 · 돌무더기는 같은 지역 안의 장면 배경입니다.</p><div class="forest-map"><span>거처</span><span>유성의 자리</span><span>계곡</span><span>돌무더기</span></div><p class="empty">다른 지역은 아직 제작 범위에 포함하지 않았습니다.</p>';else if(view==='relations'){const r=state.relations[companionId(state)+':'+state.player];$('page').innerHTML=`<h2 class="page-title">선택으로 쌓인 인연</h2><p class="empty">${state.characters[companionId(state)].name} → ${state.characters[state.player].name}</p>${meter('신뢰',r.trust,100,'gold')}${meter('호감',r.affection)}<p class="empty">신뢰는 메인 플롯의 공동 수호·동행 결말을 여는 조건입니다.<br>같은 서브 플롯을 반복해서 수치를 올릴 수 없습니다.</p>`}else{$('page').innerHTML='<h2 class="page-title">열세 갈래의 기록</h2><p class="empty">10개의 작은 선택과 3개의 큰 이야기. 완료한 선택은 되돌리지 않으며, 다른 결과는 새 역사에서 볼 수 있습니다.</p><div class="cards">'+[...plots.subs,...plots.mains].map(p=>{const done=(p.kind==='sub'?state.story.completed:state.story.mainDone).includes(p.id);return`<div class="card"><div class="eyebrow">${p.kind==='sub'?'SUB PLOT':'MAIN PLOT'} · ${done?'완료':state.story.active?.plot===p.id?'진행 중':'미완료'}</div><h3>${p.title}</h3>${state.story.records.filter(r=>r.plot===p.id).map(r=>`<p>${escapeHtml(r.label)}<br>${escapeHtml(r.text)}</p>`).join('')||'<p>선택의 결과가 이곳에 기록됩니다.</p>'}</div>`}).join('')+'</div>';}}
function showDecision(){if(acting||state.story.ending)return;setupDecision(state,plots);saveAuto();draw();renderDecision();if(!$('turn-dialog').open)$('turn-dialog').showModal()}
function renderDecision(){const pending=state.pending;if(!pending)return;const n=currentNode(state,plots),p=currentPlot(state,plots);$('turn-kicker').textContent=`${state.day}일차 · 제${state.tick+1}턴${state.combat?' / 전투 라운드 '+state.combat.round:''}`;$('turn-error').textContent='';let options=[];
 if(state.combat){$('turn-title').textContent=state.combat.name;$('turn-description').textContent=`적 체력 ${state.combat.hp}/${state.combat.maxHp} · 내 체력 ${state.characters[state.player].hp}\n${['근거리','중거리','원거리'][state.combat.distance]} · 기력 ${state.characters[state.player].energy}/60`;options=[['attack','기본 공격 · 근거리'],['skill','기술 · 기력 12'],['guard','방어 · 기력 회복'],['approach','접근'],['environment','주변 환경 이용'],['dodge','회피'],['negotiate','휴전 제안'],['flee','도주'],['item','약초 사용'],['retreat','후퇴']].map(([id,label])=>({input:{type:'battle',id},label}));}
 else if(n){$('turn-title').textContent=n.title;$('turn-description').textContent=n.text;options=n.choices.map(c=>({input:{type:'choice',id:c.id},label:c.label,denied:locks(state,c.requires),hint:c.check?`${{insight:'통찰',will:'의지',power:'힘'}[c.check.stat]||c.check.stat} 판정 · 실패해도 사건 진행`:''}));if(p.kind==='sub')options.push({input:{type:'back'},label:'다른 작은 사건 살펴보기 · 턴 소모 없음'});}
 else{$('turn-title').textContent='산속에서 마주한 작은 일';$('turn-description').textContent='지금 살펴볼 사건을 고르세요. 사건을 펼쳐보는 것만으로는 턴이 흐르지 않습니다. 선택의 결과를 확정할 때 한 턴이 지나갑니다.';options=plots.subs.filter(p=>!state.story.completed.includes(p.id)).map(p=>({input:{type:'openSub',id:p.id},label:p.title,hint:'아직 겪지 않은 서브 플롯'}));options.push({input:{type:'rest'},label:'잠시 휴식한다',hint:'작은 회복 · 날짜 유지'},{input:{type:'sleep'},label:'거처에서 밤을 보낸다',hint:'날짜 +1 · 체력과 기력 회복'});}
 $('choices').innerHTML=options.map((o,i)=>`<button data-option="${i}" ${o.denied?.length||acting?'disabled':''}><span>${String(i+1).padStart(2,'0')}</span><div>${escapeHtml(o.label)}${o.denied?.length?`<small>잠김 · ${o.denied.join(' / ')}</small>`:o.hint?`<small>${escapeHtml(o.hint)}</small>`:''}</div></button>`).join('');document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>perform(options[Number(b.dataset.option)].input,pending.id));}
function perform(input,expectedId){if(acting||!state.pending)return;acting=true;try{const result=storyAction(state,input,plots,expectedId);if(!result.ok){$('turn-error').textContent=result.error;return}state=result.state;saveAuto();if(result.committed){$('turn-dialog').close();view='story'}else renderDecision();draw();}catch(e){$('turn-error').textContent='선택을 처리하지 못했습니다. '+e.message}finally{acting=false;const error=$('turn-error').textContent;draw();if($('turn-dialog').open)renderDecision();$('turn-error').textContent=error}}
$('next-turn').onclick=showDecision;$('fold-turn').onclick=()=>$('turn-dialog').close();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{view=b.dataset.page;draw()});
function startNew(){openModal('<div class="eyebrow">NEW CHAPTER</div><h2>누구의 선택을 기록할까요?</h2><p>같은 산에서 시작하지만, 준비와 대응에 따라 다른 큰 사건과 결말로 이어집니다.</p><label for="seed">세계 시드</label><input id="seed" type="number" value="'+Math.floor(Math.random()*999999)+'"><div class="select-characters"><button id="new-jihyo">지효<small>통찰 · 흔들리는 힘</small></button><button id="new-baekho">백호<small>힘 · 수호자의 의무</small></button></div><p>새 역사는 현재 v0.3 자동 저장을 교체합니다.<br>v0.2 저장은 덮어쓰지 않습니다. 필요하면 먼저 기록을 내보내 주세요.</p>');for(const id of['jihyo','baekho'])$('new-'+id).onclick=()=>{state=newStory(world,id,Number($('seed').value));saveAuto();view='story';$('modal').close();draw()}}$('new').onclick=startNew;
function exportSave(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='white-meteor-v03-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('export').onclick=exportSave;$('save').onclick=()=>{try{localStorage.setItem(MANUAL,JSON.stringify(state));message('수동 저장 완료 · 선택 대기와 전투 상태 포함')}catch{message('저장할 수 없습니다. 기록 파일로 내보내 주세요.')}};
$('load').onclick=()=>{openModal('<h2>기록 이어가기</h2><p>불러온 기록이 현재 v0.3 진행을 교체합니다. 이전 버전은 날짜·턴·주인공 능력치를 옮기고, 새 플롯은 처음부터 시작합니다.</p><button class="wide" id="manual-load">v0.3 수동 저장 불러오기</button><button class="wide" id="import-file">저장 JSON 파일 가져오기</button><button class="wide" id="legacy-load">이 브라우저의 v0.2 자동 저장 가져오기</button>');$('manual-load').onclick=()=>loadText(localStorage.getItem(MANUAL));$('legacy-load').onclick=()=>loadText(localStorage.getItem('meteor-auto'));$('import-file').onclick=()=>$('import').click()};function loadText(text){try{if(!text)throw Error('저장된 기록이 없습니다.');const next=restoreStory(JSON.parse(text),world,plots);state=next;saveAuto();view='story';$('modal').close();draw();message('기록을 불러왔습니다.')}catch(e){message(e.message)}}$('import').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>8000000)message('8MB 이하 파일을 선택하세요.');else loadText(await f.text())}e.target.value=''};
$('settings').onclick=()=>openModal('<h2>산속의 열세 갈래 · v0.3</h2><p>산속 한 지역 / 서브 플롯 10개 / 메인 플롯 3개 / 준비된 선택지 66개 / 결말 8개.</p><p>서브 플롯을 3개·6개·10개 마치면 각각 메인 플롯이 이어집니다. 작은 사건의 선택은 능력치, 신뢰, 단서와 위협에 영향을 주며 후속 선택을 해금합니다.</p><p>이 버전은 무한 AI 채팅이 아닌 분기형 비주얼노벨 구조입니다. API 연결 없이 전부 플레이할 수 있습니다. 대사와 결과는 준비된 콘텐츠에서 나오며 판정만 시드 난수를 사용합니다.</p><p>일반 행동은 날짜를 바꾸지 않습니다. 작은 사건 목록에서 밤을 보내야 날짜가 넘어갑니다. 메인 사건과 전투 도중에는 먼저 상황을 해결해야 합니다.</p><p>전투 패배는 중상과 후퇴로 이어지며 이야기는 계속됩니다. 세부 사건·대사·분기는 게임용 창작 초안으로, 원작 확정 설정을 뜻하지 않습니다.</p>');
draw();if(restoreError)message('기존 자동 저장 읽기 실패. 원본은 유지됩니다: '+restoreError);else if(first)startNew();
